mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io, *orig_io;
  int oflags;

  mrb_check_type(mrb, copy, MRB_TT_DATA);
  io = (struct mrb_io *)mrb_data_get_ptr(mrb, copy, &mrb_io_type);

  if (io != NULL) {
    if (io->fd != -1) {
      mrb_raise(mrb, E_RUNTIME_ERROR, "initialize copied IO");
    }
    mrb_data_clear(mrb, copy);
  }

  orig = mrb_iv_get(mrb, copy, mrb_intern_lit(mrb, "orig"));
  if (mrb_nil_p(orig)) {
    orig = mrb_obj_value((struct RObject*)mrb_get_args(mrb, "o", &orig));
  }
  mrb_check_type(mrb, orig, MRB_TT_DATA);
  orig_io = (struct mrb_io *)mrb_data_get_ptr(mrb, orig, &mrb_io_type);

  oflags = fcntl(orig_io->fd, F_GETFL);
  if (oflags == -1) {
    mrb_sys_fail(mrb, "fcntl (F_GETFL)");
  }

  io = mrb_malloc(mrb, sizeof(*io));
  io->fd = dup(orig_io->fd);
  if (io->fd == -1) {
    mrb_sys_fail(mrb, "dup");
  }

  if (fcntl(io->fd, F_SETFD, 1) == -1) {
    mrb_sys_fail(mrb, "fcntl (F_SETFD)");
  }

  if (oflags & O_APPEND) {
    fcntl(io->fd, F_SETFL, oflags & ~O_APPEND);
    if (lseek(io->fd, 0, SEEK_END) == -1) {
      mrb_sys_fail(mrb, "lseek");
    }
    fcntl(io->fd, F_SETFL, oflags | O_APPEND);
  }

  io->readable = orig_io->readable;
  io->writable = orig_io->writable;
  io->sync = orig_io->sync;

  mrb_data_init(mrb, copy, io, &mrb_io_type);
  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value original;
  struct mrb_io *io;
  struct mrb_io *orig_io;

  original = mrb_get_args(mrb, "o", &copy);
  if (mrb_obj_equal(mrb, copy, original)) {
    return copy;
  }

  mrb_data_type *type = &mrb_io_type;
  mrb_data_object *data = mrb_to_data_ptr(mrb, copy);
  if (data->type != type) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type");
  }

  mrb_data_finalize(mrb, data);

  io = mrb_calloc(mrb, 1, sizeof(*io));
  if (!io) {
    mrb_raise(mrb, E_NO_MEMORY_ERROR, "failed to allocate IO object");
  }

  orig_io = mrb_cget_io(mrb, original);
  if (orig_io->fd >= 0) {
    io->fd = dup(orig_io->fd);
    if (io->fd < 0) {
      mrb_sys_fail(mrb, "dup");
    }
  }

  io->mode = orig_io->mode;
  io->path = orig_io->path;
  io->sync = orig_io->sync;

  data = mrb_data_object_alloc(mrb, mrb_class_ptr(copy), io, type);
  mrb_data_set_ptr(mrb, copy, data);

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  struct mrb_io *io = NULL;
  struct mrb_io *orig = NULL;
  mrb_value klass;

  if (!mrb_obj_is_kind_of(mrb, copy, mrb_class_get(mrb, "IO"))) {
    mrb_raise(mrb, E_TYPE_ERROR, "io copy must be IO type");
  }

  io = (struct mrb_io*)DATA_PTR(copy);
  if (!io) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "uninitialized IO");
  }

  orig = (struct mrb_io*)DATA_PTR(mrb_iv_get(mrb, copy, mrb_intern_lit(mrb, "orig")));
  if (!orig) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "uninitialized original IO");
  }

  if (io->fd != -1) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "already initialized IO");
  }

  klass = mrb_obj_class(mrb, mrb_obj_value(io));
  mrb_data_init(mrb, &copy, mrb_data_init, mrb_data_free);

  if (dup2(orig->fd, io->fd) == -1) {
    mrb_sys_fail(mrb, "dup2");
  }

  fcntl(io->fd, F_SETFD, 0);

  if (orig->mode & IO_R) {
    io->mode |= IO_R;
  }
  if (orig->mode & IO_W) {
    io->mode |= IO_W;
  }
  if (orig->mode & IO_APPEND) {
    io->mode |= IO_APPEND;
  }
  if (orig->mode & IO_SYNC) {
    io->mode |= IO_SYNC;
  }

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  struct mrb_io *io;
  mrb_value orig;
  mrb_value result;
  int fd;
  int flags;

  orig = mrb_get_args(mrb, "o", &copy);
  if (mrb_obj_equal(mrb, copy, orig)) {
    return copy;
  }

  mrb_data_type *orig_type = mrb_get_datatype(mrb, orig);
  if (orig_type != &mrb_io_type) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type");
  }

  io = (struct mrb_io *)mrb_data_get_ptr(mrb, orig, &mrb_io_type);
  if (!io) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "io not initialized");
  }

  fd = dup(io->fd);
  if (fd == -1) {
    mrb_sys_fail(mrb, "dup");
  }

  flags = fcntl(fd, F_GETFL);
  if (flags == -1) {
    mrb_sys_fail(mrb, "fcntl");
  }

  if (flags & O_APPEND) {
    flags |= O_APPEND;
  }

  if (flags & O_NONBLOCK) {
    flags |= O_NONBLOCK;
  }

  result = mrb_obj_new(mrb, mrb_class_ptr(orig), 0, NULL);
  io = (struct mrb_io *)mrb_data_get_ptr(mrb, result, &mrb_io_type);
  io->fd = fd;
  io->flags = flags;
  io->sync = io->sync;
  io->readable = io->readable;
  io->writable = io->writable;

  mrb_set_args(mrb, 1, &copy);
  return result;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  struct RClass *io_class = mrb->object_class;
  mrb_value orig = mrb_get_arg(0);
  mrb_value result = mrb_class_new_instance(0, NULL, io_class);

  if (!mrb_io_p(orig)) {
    mrb_raisef(mrb, E_TYPE_ERROR, "wrong argument type %T (expected IO)", orig);
  }

  mrb_funcall(mrb, copy, "initialize_dup", 1, orig);

  return copy;
}
